fn shell_game(n: i32, x: i8) -> i8 {
    // Reduce the number of moves modulo 6, since every 6 moves
    // (swap01, swap12) repeated three times returns the token to its start.
    let moves = (n % 6) as u8;
    // proof-obligation: moves is in 0..6
    assert(moves < 6);

    // Work with an unsigned small integer for easy pattern matching.
    let mut pos = x as u8;
    // proof-obligation: pos is in 0..3
    assert(pos <= 2);

    // perform exactly `moves` swaps
    for i in 1..=moves {
        // loop invariants at the head of each iteration
        assert(i <= moves);
        assert(pos <= 2);

        if i % 2 == 1 {
            // Odd move: swap positions 0 <-> 1
            match pos {
                0 => pos = 1,
                1 => pos = 0,
                _ => {} // pos == 2 stays
            }
        } else {
            // Even move: swap positions 1 <-> 2
            match pos {
                1 => pos = 2,
                2 => pos = 1,
                _ => {} // pos == 0 stays
            }
        }

        // post-swap invariant
        assert(pos <= 2);
    }

    // final check before return
    assert(pos <= 2);
    pos as i8
}

